  gl: { 'wakker': 'проснулся (wakker worden)', 'moe': 'усталый', 'omdat': 'потому что', 'oefende': 'упражнялся', 'vaart': 'канал (судоходный)', 'torens': 'башни', 'of': 'ли', 'hoewel': 'хотя', 'logisch': 'логично' },
  tf: ['Rik was moe omdat Joop de hele nacht had gezongen.|T', 'Joop zegt dat hij zong.|F # «Ik zong niet,» zei Joop. «Ik oefende mijn g.»', 'Rik weet zeker dat er goede patat is in Delft.|F # «Ik weet niet of ze hier goede patat hebben.»'],
  ch: ['Waarom denkt Joop dat er patat is in Delft?|omdat er kerken en dus toeristen zijn|omdat Rik dat zegt|omdat hij het ruikt # «Als er toeristen zijn, is er nog meer patat.»'],
